<?php require_once __DIR__.'/functions.php'; require_once __DIR__.'/app_init.php';require_login();$pdo=dogvive_db();$uid=dogvive_user_id();if($_SERVER['REQUEST_METHOD']==='POST'){try{$rid=(int)($_POST['id_reserva']??0);$rating=(int)($_POST['calificacion']??0);$comment=trim((string)($_POST['comentario']??''));if($rating<1||$rating>5||mb_strlen($comment)<5)throw new RuntimeException('Elige de 1 a 5 estrellas y escribe un comentario de al menos 5 caracteres.');$q=$pdo->prepare("SELECT id_reserva FROM reserva WHERE id_reserva=? AND id_usuario=? AND Estado='Completada'");$q->execute([$rid,$uid]);if(!$q->fetch())throw new RuntimeException('Solo puedes calificar una reserva completada de tu cuenta.');$dupe=$pdo->prepare('SELECT id_resena FROM resena WHERE id_reserva=? AND id_usuario=?');$dupe->execute([$rid,$uid]);if($dupe->fetch())throw new RuntimeException('Ya calificaste esta reserva.');$ins=$pdo->prepare('INSERT INTO resena (Calificacion,Comentario,Fecha,id_usuario,id_reserva) VALUES (?,?,CURDATE(),?,?)');$ins->execute([$rating,$comment,$uid,$rid]);dogvive_flash('success','Gracias, tu calificación fue guardada.');header('Location: '.base_url().'/reservas.php');exit;}catch(Throwable $e){dogvive_flash('error',$e instanceof RuntimeException?$e->getMessage():'No se pudo guardar la calificación.');header('Location: '.base_url().'/calificar.php?id='.(int)($_POST['id_reserva']??0));exit;}}
$rid=(int)($_GET['id']??0);$q=$pdo->prepare("SELECT r.*,s.Nombre AS servicio,m.Nombre AS mascota FROM reserva r LEFT JOIN servicio s ON s.id_servicio=r.id_servicio LEFT JOIN mascota m ON m.id_mascota=r.id_mascota WHERE r.id_reserva=? AND r.id_usuario=? AND r.Estado='Completada'");$q->execute([$rid,$uid]);$r=$q->fetch();$error=dogvive_flash('error');start_app('Calificar sesión','reservas');page_wrap_start('Calificar sesión','Comparte tu experiencia para ayudar a otros usuarios.');if($error)echo '<div class="error-box">'.e($error).'</div>';if(!$r)echo '<div class="card"><p>Para calificar, selecciona una reserva completada que todavía no hayas calificado.</p>'.btn('Volver a reservas',page_url('reservas'),'btn-secondary').'</div>';else{ ?>
<div class="card form-box" style="max-width:700px"><h3><?= e((string)$r['servicio']) ?> · <?= e((string)$r['mascota']) ?></h3><form method="post"><input type="hidden" name="id_reserva" value="<?= (int)$rid ?>"><label>Calificación<select name="calificacion" required><option value="">Selecciona estrellas</option><option value="5">★★★★★ — Excelente</option><option value="4">★★★★ — Muy bueno</option><option value="3">★★★ — Bueno</option><option value="2">★★ — Regular</option><option value="1">★ — Malo</option></select></label><label>Reseña<textarea name="comentario" rows="5" minlength="5" maxlength="2000" required placeholder="Cuéntanos cómo fue la experiencia..."></textarea></label><button class="btn btn-primary full" type="submit">Guardar calificación</button></form></div><?php }page_wrap_end();end_app();
